using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in EF Core 9.
        // Fix: Explicitly set the old property name for backward compatibility with existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id format changed from "EntityType|KeyValue" to just "KeyValue" in EF Core 9.
        // Fix: Explicitly configure the old id format using HasJsonIdProperty with a shadow property,
        // or use the backward-compat id factory. Simplest fix is opting in to the legacy format:
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);

        // Breaking change 3: Indexes are not supported in Azure Cosmos DB provider — this threw
        // at runtime starting in EF Core 9 (previously silently ignored).
        // Fix: Remove the unsupported HasIndex call.
        // modelBuilder.Entity<Blog>().HasIndex(b => b.Name); // REMOVED
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

