class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: In EF Core 9, Cosmos DB provider uses full-document replacement
        // (PUT) instead of patch (PATCH) on SaveChanges by default for tracked entities.
        // This is semantically equivalent for this pattern (read-modify-write), so no code
        // change needed here, but be aware of concurrency implications with partial updates.
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

