class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var entity = modelBuilder.Entity<Blog>();

        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in EF Core 9.
        // Fix: Explicitly keep the old property name for existing documents.
        entity.HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id property value changed from "EntityType|KeyValue" to just "KeyValue".
        // Fix: Configure id generation to use the legacy format with "__id" containing "Blog|{Id}".
        entity.Property<string>("__id");
        entity.HasKey("__id");

        // Breaking change 3: HasIndex is not supported on Cosmos provider — now throws at model
        // validation time in EF Core 9 (was silently ignored in EF Core 8).
        // Fix: Remove the HasIndex call entirely.
        // entity.HasIndex(b => b.Name); // REMOVED

        // Breaking change 4 (raw SQL): Queries like
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // still work because we preserved "Discriminator" above. No SQL change needed.
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

